mapper.select:
SELECT ksm.id, ksm.type, ksm.media_platform AS mediaPlatform, ksm.third_platform AS thirdPlatform, ksm.platform_account_id AS platformAccountId, ksm.platform_account_name AS platformAccountName, ksm.publish_time AS publishTime, ksm.url, ksm.url_hash AS urlHash, ksm.title, ksm.insert_timestamp AS insertTimestamp, ksm.insert_time AS insertTime, ksm.follower_count AS followerCount, ksm.view_count AS viewCount, ksm.play_count AS playCount, ksm.comment_count AS commentCount, ksm.like_count AS likeCount, ksm.repost_count AS repostCount, ksm.unique_key AS uniqueKey, ksm.create_time AS createTime, ksm.create_user_id AS createUserId, ksm.create_user_name AS createUserName, ksm.update_time AS updateTime, ksm.update_user_id AS updateUserId, ksm.update_user_name AS updateUserName
FROM kol_social_media ksm WHERE ${params.sqlMap.default} AND ksm.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ksm.create_time DESC
